    <script>
        (() => {
            const values = { density: ['comfortable', 'compact'], tableRows: ['10', '25', '50'] };
            const keys = { density: 'itoken.dashboard.density', tableRows: 'itoken.dashboard.table-rows' };
            try {
                for (const name of Object.keys(keys)) {
                    const saved = localStorage.getItem(keys[name]);
                    const value = values[name].includes(saved) ? saved : ({ density: 'comfortable', tableRows: '25' })[name];
                    document.documentElement.dataset[`dashboard${name[0].toUpperCase()}${name.slice(1)}`] = value;
                }
            } catch {
                document.documentElement.dataset.dashboardDensity = 'comfortable';
                document.documentElement.dataset.dashboardTableRows = '25';
            }
        })();
    </script>
